#include "timer_ui_logic.h"
#include <filesystem>
#include <fstream>
#include <functional>
#include <iostream>
#include <set>
#ifndef PET_TEST_ROOT
#define PET_TEST_ROOT "."
#endif
using namespace pet;
static int checks=0;
static void check(bool value,const char*message){++checks;if(!value)throw std::runtime_error(message);}
static void rejects(const std::function<void()>&operation){bool rejected=false;try{operation();}catch(const std::runtime_error&){rejected=true;}check(rejected,"invalid input must be rejected");}
static Seconds clockAt(int day,int hour,int minute=0,int second=0){std::tm tm{};tm.tm_year=126;tm.tm_mon=0;tm.tm_mday=day;tm.tm_hour=hour;tm.tm_min=minute;tm.tm_sec=second;tm.tm_isdst=-1;return Seconds(std::mktime(&tm));}
static void dialogueTests(){
 std::ifstream input(std::filesystem::path(PET_TEST_ROOT)/"data/dialogue.json");check(bool(input),"dialogue library exists");auto library=Json::parse(std::string((std::istreambuf_iterator<char>(input)),{}));
 Config c;c.pet=2;c.x=-900;c.scale=150;c.opacity=70;c.timer.mode=Mode::Interval;c.timer.interval=60;c.timer.start(1000);c.timer.tick(1060);c.timer.defer(1060,5);c.timer.title="Title 名前 標題";c.timer.text="Keep my reminder 原文";
 Json::Array oldProfiles;for(int i=0;i<3;++i){Json profile;profile["name"]="角色 🐾 "+std::to_string(i);profile["files"]["idle"]=std::string(64,char('a'+i))+".png";for(auto state:dialogueStates)profile["dialogues"][state]=Json::Array{"舊台詞 日本語 English "+std::to_string(i)+state,"另一句 🐾"};oldProfiles.push_back(profile);}
 Json old=c.json();old["customProfiles"]=oldProfiles;c.load(Json::parse(old.dump()),true);auto timer=c.timer.json().dump();
 for(int slot=0;slot<3;++slot){auto&profile=c.profiles[size_t(slot)];check(profile.dialogues.dump()==oldProfiles[size_t(slot)]["dialogues"].dump(),"legacy text migrates without translation or loss");for(int lang=1;lang<3;++lang)for(auto state:dialogueStates)check(validDialogueList(profile.dialogueFor(Language(lang))[state]).empty(),"migration never copies old text into English or Japanese");
  check(c.selectCustom(slot),"profile still selectable");for(int lang=0;lang<3;++lang){c.language=Language(lang);c.dialogueLanguage=lang==2?"en-US":"ja-JP";const Json&pack=lang==0?library:library["languages"][languageCode(c.language)];for(auto state:dialogueStates){auto fallback=dialogueCandidates(c,library,state);check(fallback==(lang==0?validDialogueList(oldProfiles[size_t(slot)]["dialogues"][state]):validDialogueList(pack["generic"][state])),"missing locale falls back only to UI-language generic");std::string first=(lang==0?"繁體中文 🐾":lang==1?"English 🐾":"日本語 🐾")+std::to_string(slot)+state;profile.setDialogue(c.language,state,Json::Array{first,first+" 2"});check(dialogueCandidates(c,library,state)==std::vector<std::string>({first,first+" 2"}),"each profile language and state has independent original text");std::string previous;for(unsigned n=0;n<8;++n){auto before=previous;chooseDialogue(dialogueCandidates(c,library,state),previous,n);check(previous!=before,"custom dialogue avoids consecutive repeats");}}
   check(c.timer.json().dump()==timer&&c.x==-900&&c.scale==150&&c.opacity==70,"language and role changes preserve live timer and desktop settings");}
 }
 Config restored;restored.load(Json::parse(c.json().dump()),true);check(restored.json().dump()==c.json().dump(),"restart and update roundtrip preserves all three languages and tasks");
 for(int slot=0;slot<3;++slot){check(restored.selectCustom(slot),"restored profile selectable");for(int lang=0;lang<3;++lang){restored.language=Language(lang);for(auto state:dialogueStates){std::string expected=(lang==0?"繁體中文 🐾":lang==1?"English 🐾":"日本語 🐾")+std::to_string(slot)+state;check(dialogueCandidates(restored,library,state)==std::vector<std::string>({expected,expected+" 2"}),"all saved profile/language/state routes remain isolated after switching");}}}
 for(auto&profile:restored.profiles){auto saved=profile.json();for(auto state:dialogueStates)check(validDialogueList(saved["dialogues"][state])==validDialogueList(profile.dialogueFor(Language::ZhTW)[state]),"legacy clients retain the full Traditional Chinese field without duplicate storage");}
 for(int lang=0;lang<3;++lang){restored.language=Language(lang);restored.profiles[2].setDialogue(restored.language,"pet",Json::Array{});const Json&pack=lang==0?library:library["languages"][languageCode(restored.language)];check(dialogueCandidates(restored,library,"pet")==validDialogueList(pack["generic"]["pet"]),"clear current language uses its own default");auto noLibrary=dialogueCandidates(restored,Json{},"pet");check(noLibrary==std::vector<std::string>{tr(TextId::GenericDialogue,restored.language)},"missing data library never leaks another language");}
 restored.dialogueEnabled=false;check(dialogueCandidates(restored,library,"general").empty()&&!dialogueCandidates(restored,library,"remind").empty(),"ordinary dialogue toggle never suppresses reminders");restored.dialogueEnabled=true;restored.profiles[2].dialogueEnabled=false;check(dialogueCandidates(restored,library,"wake").empty()&&!dialogueCandidates(restored,library,"remind").empty(),"profile toggle preserves reminders");
 auto sibling=restored.profiles[0].json().dump();restored.clearProfile(2);check(restored.profiles[0].json().dump()==sibling&&restored.profiles[2].dialogueLanguages.items().empty()&&restored.timer.json().dump()==timer,"clear profile preserves siblings and timer");
 Json corrupt;corrupt["dialogues"]["happy"]=Json::Array{"legacy"};corrupt["dialogueLanguages"]["en-US"]["happy"]="bad type";CustomProfile partial;partial.load(corrupt,"test");check(validDialogueList(partial.dialogueFor(Language::ZhTW)["happy"])==std::vector<std::string>{"legacy"}&&validDialogueList(partial.dialogueFor(Language::EnUS)["happy"]).empty(),"invalid locale is empty without damaging legacy text");
 corrupt["dialogueLanguages"]["zh-TW"]["general"]=Json::Array{};partial.load(corrupt,"test");check(validDialogueList(partial.dialogueFor(Language::ZhTW)["happy"])==std::vector<std::string>{"legacy"},"partial new Traditional Chinese map retains old missing states");corrupt["dialogueLanguages"]["zh-TW"]["happy"]=Json::Array{};partial.load(corrupt,"test");check(validDialogueList(partial.dialogueFor(Language::ZhTW)["happy"]).empty(),"explicit empty new array overrides legacy text");
 // Existing bounded JSON parser remains unchanged; even worst-case escaped data is rejected.
 rejects([]{Json::parse(std::string(1024*1024+1,' '));});
 std::set<std::string> ids;for(const auto&translation:translations){check(ids.insert(translation.id).second,"translation IDs remain unique");for(int lang=0;lang<3;++lang){check(translation.value[size_t(lang)]&&*translation.value[size_t(lang)],"translation complete");check(Json::parse(Json(translation.value[size_t(lang)]).dump()).str()==translation.value[size_t(lang)],"translation is valid UTF8");}}
}
static void timerTests(){
 check(hour24(12,false)==0&&hour24(12,true)==12&&hour24(1,true)==13&&hour24(11,true)==23,"12AM midnight and 12PM noon");for(int h=0;h<24;++h)check(hour24(hour12(h),h>=12)==h,"all 24 hours roundtrip");for(int h:{-1,0,13,99})rejects([&]{hour24(h,false);});for(int h:{-1,24})rejects([&]{hour12(h);});
 check(wrapNumber(12,1,1,12)==1&&wrapNumber(1,-1,1,12)==12&&wrapNumber(59,1,0,59)==0&&wrapNumber(0,-1,0,59)==59,"wheel wraps in both directions");check(wrapNumber(1,-26,1,12)==11&&wrapNumber(0,600,0,59)==0,"accelerated wheel wraps");
 int combined=0;for(int day=0;day<7;++day){combined|=weekdayBit(day);check(weekdayBit(day)==1<<((day+1)%7),"Monday-first UI retains Sunday-first stored bits");}check(combined==127&&weekdayBit(6)==1&&weekdayBit(-1)==0&&weekdayBit(7)==0,"all weekday bits and bounds");
 check(weekdayPreset(0)==0&&weekdayPreset(1)==127&&weekdayPreset(2)==62&&weekdayPreset(3)==65,"once daily weekday weekend presets");
 // Jan 5 2026 is Monday. Use local calendar conversion and simulated clocks (no waits).
 for(int days=1;days<=127;++days){Timer alarm;alarm.mode=Mode::Alarm;alarm.repeat=2;alarm.weekdays=days;alarm.alarmHour=hour24(12,false);alarm.alarmMinute=0;for(int day=5;day<=11;++day){auto simulated=clockAt(day,23,59,59);alarm.start(simulated);auto actual=local(alarm.due);check(alarm.due>simulated&&alarm.due<=clockAt(day+8,0)&&actual.tm_hour==0&&actual.tm_min==0&&(days&(1<<actual.tm_wday)),"each checked weekday mask schedules future local midnight across weeks");check(alarm.tick(alarm.due)&&alarm.pending&&alarm.running,"repeating alarm fires and stays scheduled");auto next=alarm.due;alarm.acknowledge();check(!alarm.pending&&next>simulated,"acknowledgment retains next week scheduling");}}
 Timer alarm;alarm.mode=Mode::Alarm;alarm.alarmHour=hour24(12,true);alarm.alarmMinute=0;alarm.repeat=0;alarm.start(clockAt(5,11,59,59));check(alarm.due==clockAt(5,12)&&alarm.tick(alarm.due)&&!alarm.running&&alarm.pending,"single noon alarm fires once");check(!alarm.tick(clockAt(6,12)),"single alarm never repeats");alarm.start(clockAt(5,12));check(alarm.due==clockAt(6,12),"exact boundary chooses next day");
 alarm.alarmHour=0;alarm.repeat=1;alarm.start(clockAt(11,23,59,59));check(alarm.due==clockAt(12,0),"Sunday midnight crosses into Monday");alarm.tick(alarm.due);check(alarm.due==clockAt(13,0),"daily alarm retains next local midnight");
 alarm.repeat=2;alarm.weekdays=weekdayPreset(2);alarm.alarmHour=9;alarm.start(clockAt(9,9));check(alarm.due==clockAt(12,9),"Friday weekday alarm skips weekend");alarm.weekdays=weekdayPreset(3);alarm.start(clockAt(11,9));check(alarm.due==clockAt(17,9),"Sunday weekend alarm skips working week");
 for(auto mode:{Mode::Countdown,Mode::Interval}){check(durationInput(mode,0,0,1)==1&&durationInput(mode,0,59,59)==3599,"duration lower and minute boundary");for(int minutes:{5,15,25,30,60})check(durationInput(mode,minutes/60,minutes%60,0)==minutes*60,"quick time presets");rejects([&]{durationInput(mode,0,0,0);});rejects([&]{durationInput(mode,0,60,0);});rejects([&]{durationInput(mode,0,0,60);});rejects([&]{durationInput(mode,-1,0,0);});}
 check(durationInput(Mode::Interval,24,0,0)==86400&&durationInput(Mode::Countdown,168,0,0)==604800,"existing mode-specific upper bounds");rejects([]{durationInput(Mode::Interval,24,0,1);});rejects([]{durationInput(Mode::Interval,25,0,0);});rejects([]{durationInput(Mode::Countdown,168,1,0);});rejects([]{durationInput(Mode::Alarm,1,0,0);});
 Timer task;task.interval=300;task.start(1000);check(displayedRemaining(task,1000)==300&&displayedRemaining(task,1299)==1,"live countdown remaining");task.pause(1100);check(displayedRemaining(task,9000)==200,"paused display remains stable");task.resume(9000);check(displayedRemaining(task,9000)==200&&task.tick(9200)&&displayedRemaining(task,9200)==0,"resume and pending display");task.defer(9200,5);check(displayedRemaining(task,9201)==299,"snooze display uses deferred deadline");task.pause(9230);check(displayedRemaining(task,9999)==270,"paused snooze display");task.stop();check(displayedRemaining(task,9999)==0&&clockText(90061)=="25:01:01","stopped display and long duration formatting");
}
int main(){try{dialogueTests();timerTests();std::cout<<"PASS: "<<checks<<" v1.5 dialogue migration/routing, translation, timer and calendar checks\n";return 0;}catch(const std::exception&error){std::cerr<<"FAIL: "<<error.what()<<"\n";return 1;}}
